      "id": 1,
      "claim": "A discharge of contractual duties by operation of law occurs when an external legal event beyond the parties' control makes performance impossible or unlawful, automatically excusing performance.",
      "evidence": "Restatement (Second) of Contracts §§ 261 (Impossibility of performance) and 275 (Discharge by operation of law); common‑law doctrine of impossibility/frustration.",
      "weight": 0.6,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Impossibility of performance fits this definition, so it generally discharges contractual duties by operation of law.",
      "evidence": "When the subject matter is destroyed, a law changes, or another unforeseeable event renders performance objectively impossible, the contract is discharged under the rule in step 1.",
      "weight": 0.4,
      "depends_on": [1]
    }
  ],
  "considered": [
    {
      "answer": "A (Novation)",
      "reason_rejected": "Novation is a discharge by agreement; it requires the parties' consent to substitute a new contract, not an automatic legal discharge."
    },
    {
      "answer": "B (Accord and satisfaction)",
      "reason_rejected": "Accord and satisfaction is also a discharge by agreement, relying on mutual assent to accept different performance."
    },
    {
      "answer": "C (Anticipatory repudiation)",
      "reason_rejected": "Anticipatory repudiation is a breach that gives the non‑breaching party a right to sue or elect termination; it is not an automatic discharge by operation of law."
    }
  ]
}
